import{_ as t,o as a,c as i,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Using the Chainy vault","description":"Home · Inbox · Note template","frontmatter":{"title":"Using the Chainy vault","description":"Home · Inbox · Note template","source":"docs/brain/vault-guide.md","category":"Other documents","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/brain/vault-guide.md","filePath":"content/docs/brain/vault-guide.md"}'),o={name:"content/docs/brain/vault-guide.md"};function r(s,e,d,c,h,l){return a(),i("div",null,[...e[0]||(e[0]=[n('<div><h1 id="using-the-chainy-vault">Using the Chainy vault<a class="header-anchor" href="#using-the-chainy-vault" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/home.html">Home</a> · <a href="/Chainy-Docs/content/docs/brain/inbox/index.html">Inbox</a> · <a href="/Chainy-Docs/content/docs/brain/templates/project-note.html">Note template</a></p><h2 id="open-and-navigate">Open and navigate<a class="header-anchor" href="#open-and-navigate" aria-label="Link to this section">​</a></h2><p>In Obsidian, choose <strong>Open folder as vault</strong> and select <code>O:/Documents/GitHub/Chainy/docs</code>. Open <code>Home.md</code> from the file explorer or Quick switcher (<code>Ctrl+O</code>). This uses the repository&#39;s actual Markdown files; editing a note edits its source document.</p><p>Start with Home&#39;s five essentials. Use the seven numbered maps for a specific topic, search for exact terms and use Backlinks to see which notes refer to a document. The <a href="/Chainy-Docs/content/docs/documentation-index.html">documentation index</a> provides role-specific routes.</p><p>Relative Markdown links work in Obsidian and the documentation viewer. The vault settings enable relative links and automatic updates on rename. Keep stable filenames where external links may depend on them. See Obsidian&#39;s <a href="https://obsidian.md/help/manage-vaults">vault workflow</a> and <a href="https://obsidian.md/help/links">internal-link guide</a> for reference.</p><h2 id="make-the-graph-readable">Make the graph readable<a class="header-anchor" href="#make-the-graph-readable" aria-label="Link to this section">​</a></h2><p>For a compact map of the project, set Graph view search to <code>file:Home OR path:brain/0</code>. For a source document&#39;s immediate connections, open its Local graph. For an active-document view, filter out archives and historical pointers with <code>-path:archive -tag:#topic/history</code>. Add <code>-path:media -path:brain/templates -path:brain/inbox</code> when those notes obscure the working structure.</p><p>A prepared preset exists at <code>.obsidian/graph-chainy-preset.json</code>; its activation in the running app has not been verified. Its saved filter predates the expanded historical-pointer set, so add the history-tag exclusion when using it. If applying the preset manually, close this vault before copying it over <code>.obsidian/graph.json</code>, then reopen it. Graph filters hide nodes from the view, not files from the vault.</p><table><thead><tr><th>Color</th><th>Topic</th></tr></thead><tbody><tr><td>White</td><td>Home and navigation maps</td></tr><tr><td>Blue</td><td>Overview</td></tr><tr><td>Gold</td><td>Decisions</td></tr><tr><td>Green</td><td>Gameplay</td></tr><tr><td>Cyan</td><td>Learning</td></tr><tr><td>Purple</td><td>Engineering</td></tr><tr><td>Pink</td><td>Art and UI</td></tr><tr><td>Orange</td><td>Delivery</td></tr><tr><td>Lime</td><td>Evidence</td></tr><tr><td>Slate</td><td>History</td></tr></tbody></table><p>Colors follow topic tags, not approval status. Existing filenames remain the graph&#39;s node labels. The <a href="https://obsidian.md/help/plugins/graph">official graph guide</a> describes filters and color groups.</p><h2 id="capture-and-maintain">Capture and maintain<a class="header-anchor" href="#capture-and-maintain" aria-label="Link to this section">​</a></h2><ol><li>Create a note in <code>brain/inbox</code>, the configured new-note folder.</li><li>Insert the <code>project-note</code> template through Obsidian&#39;s Templates command.</li><li>Record a question, finding or decision with its source, date and status.</li><li>Link the note from its primary topic map and link back to that map.</li><li>Resolve it in the authoritative document and retain a pointer to the result.</li></ol><p>Use statuses such as proposed, confirmed, observed or superseded. A proposal becomes confirmed through explicit decision evidence, not a folder move. Keep detailed requirements in their source documents and navigation in maps. Earlier designs belong behind <a href="/Chainy-Docs/content/docs/brain/07-sources.html">Sources and history</a>.</p><p>The team board remains the task editing interface, and Sean owns authored project documentation. The viewer may publish Markdown notes, including inbox notes; keep participant records, identity maps, credentials and signing keys outside this repository. Only built-in Obsidian features are configured; community plugins and sync are not required.</p></div>',1)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
